 function updateStick(e){if(!touchOrigin)return;let x=e.clientX-touchOrigin.x,y=e.clientY-touchOrigin.y,len=Math.hypot(x,y);if(len>28){x=x/len*28;y=y/len*28;}move={x:x/28,y:y/28};knob.style.transform=`translate(${x}px,${y}px)`;}
 joystick.addEventListener('pointermove',updateStick);const releaseStick=()=>{touchOrigin=null;move={x:0,y:0};knob.style.transform='';};joystick.addEventListener('pointerup',releaseStick);joystick.addEventListener('pointercancel',releaseStick);joystick.addEventListener('lostpointercapture',releaseStick);$('touchDash').onclick=dash;
